INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百〇六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cb7c4e8e14cca0f06693158578b4b0287925c9b1/content/books/zizhi-tongjian/vol-287/year-0947/part-02/sources/library/jiuwudaishi-106-liu-shenjiao/source.txt", "note": "《旧五代史》卷一百〇六，段落 jiu-wudaishi-205deb4a7860-p002527；EPUB电子本，纸本及异文待核", "id": "2e7a55ae-47dd-5b09-a2a9-154ba69e599b"}, {"title": "资治通鉴·后汉纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cb7c4e8e14cca0f06693158578b4b0287925c9b1/content/books/zizhi-tongjian/vol-287/year-0947/part-02/sources/library/tongjian-287-947-jinzhou-north-return/source.txt", "note": "《资治通鉴》后汉纪二，段落 zizhi-tongjian-a63549944a71-p003406；电子底本待考，分段待核", "id": "b4721b35-1a13-5f3c-903a-56c304cad0e9"}, {"title": "资治通鉴·后汉纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/52874e45c7cb04fd601bd528e1c87122d4b092b3/content/books/zizhi-tongjian/vol-287/year-0947/part-01/sources/library/tongjian-287-947-southern-march/source.txt", "note": "《资治通鉴》后汉纪二，段落 zizhi-tongjian-a63549944a71-p003405；电子底本待考，分段待核", "id": "976d64d2-2573-5dc3-8ab9-6d43fac44d20"}, {"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/52874e45c7cb04fd601bd528e1c87122d4b092b3/content/books/zizhi-tongjian/vol-287/year-0947/part-01/sources/library/jiuwudaishi-100-may-march/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002434；EPUB电子本，纸本及异文待核", "id": "e8f35e00-113d-5b0f-b315-5fbfb97263d9"}, {"title": "旧五代史·卷五十一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a5f6c36376aec96cc635a266cd774a64d3733ea7/content/books/zizhi-tongjian/vol-286/year-0947/part-10/sources/library/jiuwudaishi-051-li-congyi/source.txt", "note": "《旧五代史》卷五十一，段落 jiu-wudaishi-205deb4a7860-p001387；EPUB电子本，纸本及异文待核", "id": "7ff2a823-7208-54e1-a2ef-e7ec344ed66c"}, {"title": "宋史·巻二百六十一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e13dd68e0caa3222d6fb3adad85c0ad8d6bd39d8/content/books/zizhi-tongjian/vol-286/year-0947/part-09/sources/library/songshi-261-li-wanchao/source.txt", "note": "《宋史》巻二百六十一，段落 songshi-9c6e46fee832-p058020；EPUB电子本，纸本及异文待核", "id": "c73dc5ed-1158-5779-960a-9067a0ce054f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "翟令奇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年担任泽州刺史，起初拒守，后接受李万超的劝说，向史弘肇投降。生卒年未载。", "biography": null, "status": "draft", "id": "b605c4d7-4085-532b-9bdf-1b4a7c447b23"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}, {"name": "李万超", "aliases": ["李萬超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋军出身的指挥使。947年驻潞州时，率众入府杀死契丹委任的赵行迁，推王守恩为主帅。《宋史》李万超传补证这一行动。生卒年暂未录入。", "biography": null, "status": "draft", "id": "7b5e692a-1d2f-5684-b29b-59f01d14f44d"}, {"name": "崔廷勋", "aliases": ["崔廷勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "河内人。947年正月《资治通鉴》称他为大同节度使兼侍中，耶律德光派他率兵看守迁到封禅寺的石重贵及家人。《旧五代史》称为蕃大将崔廷勋，未另建同名人；生卒年未载。", "biography": null, "status": "draft", "id": "43995ba6-a8ce-5d3a-86dd-43d3def50195"}, {"name": "耿崇美", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹通事。946年十二月杜重威降后，奉命到易州诱说守军投降，并杀死刺史郭璘。生卒年未载。", "biography": null, "status": "draft", "id": "60458ef5-e4bc-5d29-b338-25090e903595"}, {"name": "拽剌（西奚王）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "西奚王李绍威的儿子，在父亲去世后继位。耶律德光从上党北归时，他前往迎接并归降。", "biography": null, "status": "draft", "id": "4098a81e-f684-5a3e-a8d7-3bf67a400198"}, {"name": "张遇", "aliases": ["張遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年嵩山武装首领，拥立后梁嗣密王朱乙为天子，率众袭击郑州，被方太击退，后杀朱乙请降。与南唐境内的张遇贤分别识别，生卒年未载。", "biography": null, "status": "draft", "id": "993c8408-1ec1-54c9-9555-8b9be4e84d55"}, {"name": "武行德", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州榆次人。947年受契丹命运送晋朝铠甲兵器，途中与军士夺取兵器、杀契丹监军，继而占据河阳。生卒年尚未录入。", "biography": null, "status": "draft", "id": "e0ed92f8-edb4-574b-83af-85088429a093"}, {"name": "赵匡赞", "aliases": ["趙匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵延寿的儿子。947年正月受耶律德光任命为护国节度使。生卒年未载。", "biography": null, "status": "draft", "id": "ad59529e-c641-5bb7-bde5-3749239fd1d3"}, {"name": "萧翰", "aliases": ["蕭翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。946年十一月条下记他与通事刘重进带兵绕到晋军后方，截断粮道及归路，进至栾城接受驻军投降。《资治通鉴》称他是契丹主耶律德光的舅舅，《辽史》保存了不同的亲属说法并质疑相关姓名起源说；具体亲属关系暂待核对。生卒年本批未核。", "biography": null, "status": "draft", "id": "defe15da-7bbc-56ed-9d88-0ec31a88fcaf"}, {"name": "张环（晋宦官）", "aliases": ["張環（晉宦官）"], "era": "五代十国", "birth_year": null, "death_year": 947, "description": "晋朝宦官。947年拒绝将滋德宫宫人交给萧翰，遭萧翰拘押并用刑杀害。与渝州刺史张环分别建档。", "biography": null, "status": "draft", "id": "a60fdf6e-114d-5fc0-8b16-a1589e61de86"}, {"name": "高谟翰", "aliases": ["高謨翰", "高模翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：高谟翰，契丹前锋将领。", "biography": null, "status": "draft", "id": "70516658-fa9a-5bd1-8a0a-55b9844d4772"}, {"name": "李从益", "aliases": ["李從益"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李从益，获许王爵者。", "biography": null, "status": "draft", "id": "2d5dc982-595f-53af-8762-1255e0d9723d"}, {"name": "王淑妃", "aliases": ["花见羞", "花見羞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王淑妃，为求出所借宫中渠道。", "biography": null, "status": "draft", "id": "db6392e5-1b9a-5a9d-a338-bcfe97719238"}, {"name": "王松", "aliases": ["王鬆"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年原任礼部尚书，萧翰拥立李从益后，将王松任为宰相。《旧五代史》写作王鬆，并记为左丞相。生卒年未载。", "biography": null, "status": "draft", "id": "58e91c2f-68cc-5873-97db-7ffcb43c5690"}, {"name": "赵远", "aliases": ["趙遠", "赵上交", "趙上交"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：赵远，六军判官、司谏郎中、谏者。", "biography": null, "status": "draft", "id": "cb4acc0b-f3ec-52fa-9349-c01b93a95023"}, {"name": "翟光邺", "aliases": ["翟光鄴", "翟光業", "翟光业"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：翟光邺，受遣察安的皇城使。", "biography": null, "status": "draft", "id": "4b6400da-2b69-5857-b364-3106a40c1d45"}, {"name": "王景崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。937年担任引进使，受命劝秘琼接受任命。史书记载他是邢州人。", "biography": null, "status": "draft", "id": "5f673eda-0daa-5174-926f-dca3e0982614"}, {"name": "刘祚", "aliases": ["劉祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任北来指挥使，萧翰拥立李从益后，任他暂掌侍卫亲军并兼在京巡检。生卒年未载。", "biography": null, "status": "draft", "id": "21c9440b-64f1-5c2e-9fc9-db2da16d0c73"}, {"name": "刘晞", "aliases": ["劉晞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "涿州人，在契丹曾任枢密使、同平章事及燕京留守。947年任西京留守，到洛阳后责斥奚王慢待赵在礼。与后晋官员刘昫字形、职务不同，暂不合并；生卒年未载。", "biography": null, "status": "draft", "id": "a5949823-5190-5e38-a780-eb04d4e680a5"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "刘审交", "aliases": ["劉審交"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字求益，幽州文安人。947年萧翰在汴州时重新任用他为三司使。萧翰北归后，他反对闭城拒守，主张听从王淑妃的迎接刘知远方案。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9999edd0-1ba8-57b3-92d5-504e71c4f459"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "麻答", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领，《资治通鉴》称为耶律德光的从弟。944年二月由周儒引导从马家口渡河，攻郓州北津，以接应杨光远。个人其他名字及生卒年本批未核。", "biography": null, "status": "draft", "id": "5911d4cb-fa8a-51ff-a1e4-44450396116a"}, {"name": "高奉明", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "原任武州刺史。947年五月，耶律阮北归前任命他为安国节度使。生卒年未载。", "biography": null, "status": "draft", "id": "3583b089-97ec-5a72-abac-640a761b3642"}, {"name": "徐台符", "aliases": ["徐臺符"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武强人，后晋金部郎中、知制诰。944年六月戊辰任翰林学士。生卒年本段未载。", "biography": null, "status": "draft", "id": "28c5a951-7fb9-591a-b527-988ede5145c7"}, {"name": "李澣", "aliases": ["李浣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李涛的弟弟，后晋翰林学士。《资治通鉴》说他多次酒后失当，石敬瑭不喜欢他；940年九月翰林学士职务被撤销、事务归中书舍人。《旧五代史》同期学士名写李浣，另记他调吏部员外郎，保留字形说明。生卒年未载。", "biography": null, "status": "draft", "id": "cc1a8d2a-5333-5d3b-befa-dea7a7c759a6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "史弘肇报告泽州归降", "start_year": 947, "end_year": 947, "time_original": "947年五月丁酉（报告日）", "dynasty": "五代十国", "description": "史弘肇报告泽州归降。", "phases": [], "location_name": "泽州；刘知远行营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "106a7519-2a8e-58f5-909a-faeec856c952"}, {"title": "刘知远因兵少拟召回史弘肇，苏逢吉、杨邠主张继续进军", "start_year": 947, "end_year": 947, "time_original": "947年五月丁酉奏报以前，具体日未载", "dynasty": "五代十国", "description": "刘知远因兵少拟召回史弘肇，苏逢吉、杨邠主张继续进军。", "phases": [], "location_name": "泽州；刘知远行营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "532698b1-6bbb-5cd8-898d-952d3cf58977"}, {"title": "史弘肇坚持继续进军，刘知远采纳意见", "start_year": 947, "end_year": 947, "time_original": "947年五月丁酉奏报以前，具体日未载", "dynasty": "五代十国", "description": "史弘肇坚持继续进军，刘知远采纳意见。", "phases": [], "location_name": "泽州；刘知远行营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1dc97885-e918-5663-8dfb-b26c76a05b58"}, {"title": "李万超劝翟令奇投降，翟令奇接受", "start_year": 947, "end_year": 947, "time_original": "947年五月丁酉奏报以前，具体日未载", "dynasty": "五代十国", "description": "李万超劝翟令奇投降，翟令奇接受。", "phases": [], "location_name": "泽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ed116725-b6b4-5f9e-b313-9e1a67042dc2"}, {"title": "史弘肇令李万超暂管泽州事务", "start_year": 947, "end_year": 947, "time_original": "947年五月泽州归降